"""Build a reviewed catalog from fetched listings; missing facts remain null.
Classification edits require a matching source excerpt; this is not automatic semantic inference.
"""
import json,pathlib,re
ROOT=pathlib.Path(__file__).resolve().parents[1]
# Each claim is checked against the exact retrieved listing before publication.
CURATION=[
('com.feralinteractive.rometw','Tactics','Ancient Rome','rome','Combine empire management with large real-time battles.','A turn-based campaign and real-time battles bring ancient empire building to Android. The listing specifies Android 12+, storage requirements, and supported device restrictions; check compatibility before purchasing.',[('Turn-based','turn-based campaigns'),('Real-time','real-time battles'),('Tactics','tactics'),('Ancient','antiquity'),('Roman','Roman Empire'),('Warfare','battles')]),
('com.longyoug.hmby','Turn-based','Three Kingdoms, China','jade','Govern cities and command officers in the Three Kingdoms.','Manage cities and officers in a Three Kingdoms setting. Turn-based battles account for weather, terrain, and formations. The store lists both an upfront price and in-app purchases.',[('Turn-based','turn-based'),('Tactics','Tactics'),('Ancient','Ancient china'),('Chinese','Chinese'),('Warfare','troops'),('Politics','policies'),('Illustrated','fine-lined drawing')]),
('air.com.midjiwan.polytopia','4X','Stylized civilizations','forest','Explore, research, and expand one turn at a time.','Lead a tribe through exploration, technology research, and conflict on generated maps. The developer lists offline play, single-player and multiplayer modes; in-app purchases are listed separately from the free download.',[('Turn-based','turn based'),('4X','4x'),('Warfare','warfare'),('Politics','Diplomacy'),('Low poly','low poly')]),
('com.birdshel.Uciana','4X','Deep space','space','Build a space empire and customize your fleet.','Explore generated galaxies and balance research, farming, and production. Customize ships for turn-based combat. Offline and single-player are listed by Google Play; session length has not been independently checked.',[('4X','4X'),('Turn-based','turn-based'),('Future','space faring empire'),('Space','Stars'),('Warfare','combat')]),
('com.playdigious.northgard','City builder','Norse mythology','north','Guide a Viking clan through harsh winters.','Build a settlement, assign jobs, and manage resources in a Norse-inspired land. The developer describes a campaign, multiplayer, and separately purchasable clan DLC. Offline capability is not confirmed in this captured listing.',[('City builder','Build your settlement'),('Nordic','Norse mythology'),('Fantasy','Undead Warriors'),('Survival','survive harsh winters'),('Trade','trading'),('Warfare','conquest')]),
('io.anuke.mindustry','Tower defense','Industrial worlds','modern','Build the supply chains that keep your defenses alive.','Combine factory production, tower defense, and real-time strategy. The developer describes campaigns, a map editor, co-op, and PvP; the store also lists offline and single-player modes.',[('Tower defense','tower defense'),('Real-time','RTS'),('Economic strategy','factory-building'),('Future','mechs'),('Warfare','enemies')]),
('com.unciv.app','4X','Civilization building','rome','An open-source approach to building an empire.','Research technologies, develop cities, and expand a civilization. The developer explicitly describes the game as free forever and ad-free. The listing includes offline and single-player labels; internet access is required for multiplayer.',[('4X','4X'),('City builder','expand your cities'),('No ads','no ads'),('Warfare','defeat your foes')]),
('com.corrodinggames.rts','Real-time','Mechanized warfare','modern','Command land, sea, and air forces in a classic RTS.','Build bases and control a combined army in real time. The developer lists campaign and skirmish modes, online and offline multiplayer, and saving and loading games. The description explicitly says there are no microtransactions.',[('Real-time','real-time strategy'),('Warfare','army'),('No microtransactions','no microtransactions')]),
('yio.tro.achikaps','Economic strategy','Abstract economy','forest','A free demo of a compact economic strategy game.','This is the demo edition, offering sandbox play and part of the campaign. The developer describes a simple economic strategy game without microtransactions; offline and single-player are store labels.',[('Economic strategy','economic strategy'),('Free demo','demo version'),('No microtransactions','without microtransactions')]),
('age.of.civilizations2.jakowski.lukasz','Grand strategy','Across history','japan','Shape borders through diplomacy and military tactics.','Lead civilizations through historical and custom scenarios. The developer describes diplomacy, peace treaties, a scenario editor, and a timeline stretching from early civilization into the future. Availability on a listing is not a device compatibility guarantee.',[('Grand strategy','grand strategy'),('Ancient','dawn of civilization'),('Future','far future'),('Politics','diplomacy'),('Warfare','military tactics')]),
('com.ironhidegames.android.kingdomrush','Tower defense','Medieval fantasy','castle','Defend a fantasy kingdom with towers and heroes.','Build and upgrade defenses against fantasy enemies. The developer explicitly describes offline play and cartoon battles. Google Play marks this free-download version as containing ads and in-app purchases.',[('Tower defense','tower defense'),('Fantasy','orcs'),('Medieval','Medieval'),('Cartoon','cartoon'),('Warfare','battles')]),
]
output=[]
for pkg,genre,world,art,subtitle,description,claims in CURATION:
 source=json.loads((ROOT/'data/google-play'/f'{pkg}.json').read_text());ld=source['structuredData'];text=source['pageText'];about=text.split('About this game arrow_forward',1)[1].split('Data safety',1)[0];intro=text.split('About this game',1)[0]
 # Keep only product metadata, not user reviews or personal contact details.
 source['pageText']=text.split('Data safety',1)[0]
 (ROOT/'data/google-play'/f'{pkg}.json').write_text(json.dumps(source,ensure_ascii=False,indent=2))
 evidence=[]
 for tag,quote in claims:
  if quote.lower() not in about.lower() and quote.lower() not in source['description'].lower():raise ValueError(f'{pkg}: unsupported {tag}: {quote}')
  evidence.append({'tag':tag,'basis':'Editorial mapping of listing','excerpt':quote})
 for tag in ['Offline','Single player','Multiplayer','Realistic','Stylized','Abstract']:
  if re.search(r'\b'+re.escape(tag)+r'\b',about,re.I):evidence.append({'tag':tag,'basis':'Google Play listing','excerpt':tag})
 price=ld['offers'][0];paid=float(price['price'])>0
 for tag,basis,excerpt in [('Paid download' if paid else 'Free download','Google Play price',f"{price['priceCurrency']} {price['price']}"),('Android','Google Play platform',ld['operatingSystem'])]:evidence.append({'tag':tag,'basis':basis,'excerpt':excerpt})
 ads=True if 'Contains ads' in intro else False if 'No ads' in [e['tag'] for e in evidence] else None
 iap=True if 'In-app purchases' in intro else False if 'No microtransactions' in [e['tag'] for e in evidence] else None
 if ads:evidence.append({'tag':'Contains ads','basis':'Google Play label','excerpt':'Contains ads'})
 if iap:evidence.append({'tag':'In-app purchases','basis':'Google Play label','excerpt':'In-app purchases'})
 date=source['fetchedAt'][:10];title=' '.join(ld['name'].split())
 output.append({'id':pkg,'title':title,'subtitle':subtitle,'genre':genre,'world':world,'art':art,'color':'#7f947c','description':description,'note':'Based on the developer’s store listing, not an independent playtest. Session length, difficulty, pause behavior, and daily-task pressure have not been verified.','tags':list(dict.fromkeys(e['tag'] for e in evidence)),'price':'Paid download' if paid else 'Free download','priceValue':float(price['price']),'priceCurrency':price['priceCurrency'],'priceDisplay':f"US${float(price['price']):.2f}" if paid else 'Free download','developer':ld.get('author',{}).get('name','Not listed'),'ads':ads,'inAppPurchases':iap,'duration':None,'depth':None,'sourceUrl':source['url'],'fetchedAt':source['fetchedAt'],'sourceDate':date,'region':'US','language':'English','evidence':evidence,'iconSourceUrl':ld.get('image'),'artDisclaimer':'Original editorial illustration, not a game screenshot.'})
(ROOT/'src/data/google-play.json').write_text(json.dumps(output,ensure_ascii=False,indent=2))
print(f'Published {len(output)} reviewed listings; no invented ratings, duration, or difficulty.')
